import logo from './logo.svg';
import './App.css';

function App() {
  return (
    <div className="App">
        <h1>MAIN</h1>
        <table>
            <tbody>
            <tr>
                <td>a</td>
                <td>b</td>
                <td>c</td>
                <td>d</td>
            </tr>
            <tr>
                <td>e</td>
                <td>f</td>
                <td>g</td>
                <td>h</td>
            </tr>
            </tbody>
        </table>
    </div>
  );
}

export default App;
